INSERT INTO `roles` (`name`, `description`, `is_active`) SELECT 'Admin', 'Full access to everything.', true FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `roles` WHERE `name` = 'Admin');
INSERT INTO `roles` (`name`, `description`, `is_active`) SELECT 'Customer', 'Shop customer — no dashboard access.', true FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `roles` WHERE `name` = 'Customer');
INSERT INTO `roles` (`name`, `description`, `is_active`) SELECT 'Manager', 'Runs day-to-day operations. Everything except user, role and payment-method administration.', true FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `roles` WHERE `name` = 'Manager');
INSERT INTO `roles` (`name`, `description`, `is_active`) SELECT 'Sales', 'Handles quotes, orders, customers and payments.', true FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `roles` WHERE `name` = 'Sales');
INSERT INTO `roles` (`name`, `description`, `is_active`) SELECT 'Inventory', 'Manages stock, warehouses, production and purchasing.', true FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `roles` WHERE `name` = 'Inventory');
INSERT INTO `roles` (`name`, `description`, `is_active`) SELECT 'Content Editor', 'Maintains the public website: company details, page text, FAQ, images, testimonials and blog.', true FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `roles` WHERE `name` = 'Content Editor');
INSERT INTO `role_permissions` (`role_id`, `permission_id`, `is_active`) SELECT r.`id`, p.`id`, true FROM `roles` r JOIN `permissions` p WHERE r.`name` = 'Admin' ON DUPLICATE KEY UPDATE `is_active` = true;
INSERT INTO `role_permissions` (`role_id`, `permission_id`, `is_active`) SELECT r.`id`, p.`id`, true FROM `roles` r JOIN `permissions` p ON p.`name` IN ('dashboard.view', 'customers.view', 'customers.edit', 'customers.delete', 'quotes.view', 'quotes.reply', 'quotes.edit', 'quotes.send', 'quotes.approve', 'quotes.delete', 'orders.view', 'orders.create', 'orders.edit', 'orders.payments', 'orders.adjustments', 'orders.delete', 'payment_links.view', 'payment_links.revoke', 'promo_codes.view', 'promo_codes.create', 'promo_codes.edit', 'messages.view', 'messages.edit', 'messages.delete', 'products.view', 'products.create', 'products.edit', 'products.discounts', 'products.delete', 'catalog.view', 'catalog.create', 'catalog.edit', 'suppliers.view', 'suppliers.create', 'suppliers.edit', 'suppliers.delete', 'stock.view', 'stock.create', 'stock.edit', 'stock.delete', 'warehouses.view', 'warehouses.create', 'warehouses.edit', 'raw_materials.view', 'raw_materials.create', 'raw_materials.edit', 'production.view', 'production.create', 'production.edit', 'purchase_orders.view', 'purchase_orders.create', 'purchase_orders.edit', 'staff.view', 'staff.create', 'staff.edit', 'content.view', 'content.edit', 'blog.view', 'blog.create', 'blog.edit', 'blog.delete', 'reports.view', 'settings.view', 'payment_methods.view', 'users.view', 'roles.view') WHERE r.`name` = 'Manager' AND NOT EXISTS (SELECT 1 FROM (SELECT `role_id` FROM `role_permissions`) existing WHERE existing.`role_id` = r.`id`);
INSERT INTO `role_permissions` (`role_id`, `permission_id`, `is_active`) SELECT r.`id`, p.`id`, true FROM `roles` r JOIN `permissions` p ON p.`name` IN ('dashboard.view', 'customers.view', 'customers.edit', 'quotes.view', 'quotes.reply', 'quotes.edit', 'quotes.send', 'quotes.approve', 'quotes.delete', 'orders.view', 'orders.create', 'orders.edit', 'orders.payments', 'orders.adjustments', 'payment_links.view', 'payment_links.revoke', 'promo_codes.view', 'messages.view', 'messages.edit', 'products.view', 'catalog.view', 'stock.view', 'reports.view') WHERE r.`name` = 'Sales' AND NOT EXISTS (SELECT 1 FROM (SELECT `role_id` FROM `role_permissions`) existing WHERE existing.`role_id` = r.`id`);
INSERT INTO `role_permissions` (`role_id`, `permission_id`, `is_active`) SELECT r.`id`, p.`id`, true FROM `roles` r JOIN `permissions` p ON p.`name` IN ('dashboard.view', 'orders.view', 'products.view', 'catalog.view', 'suppliers.view', 'suppliers.create', 'suppliers.edit', 'stock.view', 'stock.create', 'stock.edit', 'stock.delete', 'warehouses.view', 'warehouses.create', 'warehouses.edit', 'raw_materials.view', 'raw_materials.create', 'raw_materials.edit', 'production.view', 'production.create', 'production.edit', 'purchase_orders.view', 'purchase_orders.create', 'purchase_orders.edit', 'staff.view') WHERE r.`name` = 'Inventory' AND NOT EXISTS (SELECT 1 FROM (SELECT `role_id` FROM `role_permissions`) existing WHERE existing.`role_id` = r.`id`);
INSERT INTO `role_permissions` (`role_id`, `permission_id`, `is_active`) SELECT r.`id`, p.`id`, true FROM `roles` r JOIN `permissions` p ON p.`name` IN ('content.view', 'content.edit', 'blog.view', 'blog.create', 'blog.edit', 'blog.delete', 'messages.view') WHERE r.`name` = 'Content Editor' AND NOT EXISTS (SELECT 1 FROM (SELECT `role_id` FROM `role_permissions`) existing WHERE existing.`role_id` = r.`id`);
